#include <stdio.h>

int main(void) {
    int S, T;
    scanf("%d %d", &S, &T);

    static unsigned char adj[1001][1001];

    for (int i = 0; i < T; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        adj[x][y] = adj[y][x] = 1;
    }

    int P, validCount = 0;
    scanf("%d", &P);

    for (int i = 0; i < P; i++) {
        int N, previous, possible = 1;
        scanf("%d", &N);

        if (N > 0) {
            scanf("%d", &previous);
            for (int j = 1; j < N; j++) {
                int current;
                scanf("%d", &current);
                if (!adj[previous][current]) {
                    possible = 0;
                }
                previous = current;
            }
        }

        if (possible) {
            validCount++;
        }
    }

    printf("%d\n", validCount);
    return 0;
}
